const data = msg.payload;

const stationConfig = [
    { id: 1, run: "Start/Stop (Run) 01", fault: "Reading/Fault 01", pressure: "Oil Sensors (Spare) 01" },
    { id: 2, run: "Start/Stop (Run) 02", fault: "Reading/Fault 02", pressure: "Oil Sensors (Spare) 02" },
    { id: 3, run: "Start/Stop (Run) 03", fault: "Reading/Fault 03", pressure: "Oil Sensors (Spare) 03" },
    { id: 4, run: "Start/Stop (Run) 04", fault: "Reading/Fault 04", pressure: "Oil Sensors (Spare) 04" },
    { id: 5, run: "Start/Stop (Run) 05", fault: "Reading/Fault 05", pressure: "Oil Sensors (Spare) 05" },
    { id: 6, run: "Start/Stop (Run) 06", fault: "Reading/Fault 06", pressure: "Oil Sensors (Spare) 06" },
    { id: 7, run: "Start/Stop (Run) 07", fault: "Reading/Fault 07", pressure: "Oil Sensors (Spare) 07" },
    { id: 8, run: "Start/Stop (Run) 08", fault: "Reading/Fault 08", pressure: "Oil Sensors (Spare) 08" }
];

const mqttMsgs = [];

stationConfig.forEach(st => {
    // เช็คว่ามีข้อมูลของ station นี้ส่งมาไหม
    if (data[st.run] === undefined) return;

    const payload = {
        station_id: st.id,
        status_run: data[st.run] ? 1 : 0,
        status_fault: data[st.fault] ? 1 : 0,
        oil_pressure: data[st.pressure] || 0,
    };

    const key = `station_${st.id}`;
    const last = context.get(key);

    // ตรวจว่าค่าเปลี่ยนหรือไม่ (เพื่อลดปริมาณข้อมูล)
    const changed = !last ||
        last.status_run !== payload.status_run ||
        last.status_fault !== payload.status_fault ||
        Math.abs(last.oil_pressure - payload.oil_pressure) > 2;

    if (!changed) return;

    // เก็บค่าล่าสุดไว้เทียบรอบหน้า
    context.set(key, payload);

    // ---- ส่ง MQTT อย่างเดียว ----
    mqttMsgs.push({
        topic: `firepump/station/${st.id}/status`,
        payload
    });
});

// ส่งออกแค่ทางเดียว (Output 1 -> MQTT)
return [mqttMsgs];

// ดึงเวลาปัจจุบัน
